suppressMessages({library(dplyr); library(readr); library(ggplot2); library(tidyr)})

.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), ".."))
  else getwd()
})
PROJECT   <- .ROOT
WKBD_ROOT <- normalizePath(file.path(PROJECT, "..", ".."))
source(file.path(WKBD_ROOT, "data_workspace_2026-07", "figure_house_theme.R"))

events <- read_csv(file.path(PROJECT, "data/raw/mp_misconduct_seats_forfeited_DATA_ENTRY.csv"),
                    show_col_types = FALSE) |>
  filter(year >= 1979, year <= 2025) |>
  arrange(year)

annual <- read_csv(file.path(PROJECT, "data/processed/mp_misconduct_annual_1979_2025.csv"),
                    show_col_types = FALSE)

# ============================================================
# FIGURE — house style, two panels: annual count by category + cumulative
# ============================================================
CANVAS_W <- house_width_in()

# ⚠ REVERTED 8 Sep, PJ: "actually I like the earlier figure can you revert and relabel leave
# out mortimore and blick reference as that i for the foonote" — back to the original two-panel
# design (annual count by category + cumulative step) from 42_mp_misconduct_seats_forfeited.R,
# now in house greyscale with a proper Figure 3.3 title, and the source attribution removed from
# the subtitle (it lives in FIG33_FOOTNOTE_NOTES.md / the chapter footnote only, not on the figure
# itself — same "sources off the figure" convention as every other Ch3 figure).

plot_df <- annual |>
  select(year, n_criminal, n_censure, n_standards) |>
  pivot_longer(c(n_criminal, n_censure, n_standards), names_to = "category", values_to = "n") |>
  mutate(category = recode(category, n_criminal = "Criminal conviction",
                            n_censure = "Censure resignation",
                            n_standards = "Standards suspension + recall"))

p1 <- ggplot(plot_df, aes(x = year, y = n, fill = category)) +
  geom_col(width = 0.8, colour = "black", linewidth = 0.2) +
  scale_fill_manual(values = c("Criminal conviction" = "grey15",
                                "Censure resignation" = "grey55",
                                "Standards suspension + recall" = "grey85")) +
  scale_x_continuous(limits = c(1978, 2026), breaks = seq(1980, 2025, 5)) +
  scale_y_continuous(breaks = 0:2) +
  labs(tag = "A", subtitle = "Annual count by category", x = NULL, y = "Events", fill = NULL) +
  house_print(CANVAS_W) +
  theme(legend.position = "bottom", legend.title = element_blank())

p2 <- ggplot(annual, aes(x = year, y = n_cumulative)) +
  geom_step(colour = "grey20", linewidth = 0.6) +
  scale_x_continuous(limits = c(1978, 2026), breaks = seq(1980, 2025, 5)) +
  labs(tag = "B", subtitle = "Cumulative count", x = NULL, y = "Cumulative events") +
  house_print(CANVAS_W)

if (!requireNamespace("patchwork", quietly = TRUE)) install.packages("patchwork")
fig <- (p1 / p2) +
  patchwork::plot_layout(heights = c(2, 1)) +
  patchwork::plot_annotation(
    title = "Figure 3.3: MPs losing their seat over misconduct, 1979-2025",
    theme = theme(plot.title = element_text(face = "bold", size = pt_for(PRINTED$title, CANVAS_W)),
                  plot.margin = margin(12, 18, 12, 18))
  )

OUT <- file.path(PROJECT, "figures/fig_3_3_mp_misconduct.png")
ggsave(OUT, fig, width = CANVAS_W, height = CANVAS_W * 0.85, dpi = HOUSE_DPI, bg = "white")
cat("Figure saved:", OUT, "\n")

